window.SAOMD_STORIES[410400501]={"id":410400501,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410400501:1:1","speaker":"Alice","text":"...","pose":10540105,"background":"bg_event_swamp","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."},{"uid":"410400501:1:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410400501:2:1","speaker":"Alice","text":"Is the climate in this region\nalways so oppressive?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这个地区的气候总是那么压抑吗？"},{"uid":"410400501:2:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":3,"order":3,"actions":[{"uid":"410400501:3:1","speaker":"Kirito","text":"I'm afraid so. Leprechauns built\ntheir territory in a swamp, after\nall.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"恐怕是的。毕竟，小妖精在沼泽中建立了自己的领地。"},{"uid":"410400501:3:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":4,"order":4,"actions":[{"uid":"410400501:4:1","speaker":"Kirito","text":"Bad weather, high humidity...\nIt's not an easy place to live.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"天气不好，湿度大……住起来不太方便。"}]},{"id":5,"order":5,"actions":[{"uid":"410400501:5:1","speaker":"Eugeo","text":"But we're closing in on a Divine\nObject, so it's not all bad.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"但我们正在接近一个神物，所以这也不全是坏事。"}]},{"id":6,"order":6,"actions":[{"uid":"410400501:6:1","speaker":"Kirito","text":"Yeah, that's true.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊，确实如此。"}]},{"id":7,"order":7,"actions":[{"uid":"410400501:7:1","speaker":"Amayori","text":"Grrrr...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"呜呜……"},{"uid":"410400501:7:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":8,"order":8,"actions":[{"uid":"410400501:8:1","speaker":"Alice","text":"Seems we're not the only ones\nwho find this place unbearable.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"看来不只我们一个人觉得这里难以忍受。"},{"uid":"410400501:8:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":9,"order":9,"actions":[{"uid":"410400501:9:1","speaker":"Alice","text":"I shall permit Amayori to rest,\nseeing as we've arrived at our\ndestination.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"既然已经到达目的地了，那就让雨缘休息吧。"},{"uid":"410400501:9:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":10,"order":10,"actions":[{"uid":"410400501:10:1","speaker":"Kirito","text":"Sounds good.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"听起来不错。"},{"uid":"410400501:10:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":11,"order":11,"actions":[{"uid":"410400501:11:1","speaker":"Alice","text":"Let us find this Divine Object\nwith all haste so we may leave\nthis infernal place.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"让我们赶紧找到这个神器，这样我们就可以离开这个鬼地方了。"},{"uid":"410400501:11:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":12,"order":12,"actions":[{"uid":"410400501:12:1","speaker":"Asuna","text":"Hehehe.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵。"}]},{"id":13,"order":13,"actions":[{"uid":"410400501:13:1","speaker":"Alice","text":"What has come over you, Asuna?","pose":105401062,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"亚丝娜，你怎么了？"}]},{"id":14,"order":14,"actions":[{"uid":"410400501:14:1","speaker":"Asuna","text":"I'm just glad to hear you say you\nwant to go back to the house...","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"很高兴听到你说你想回屋……"}]},{"id":15,"order":15,"actions":[{"uid":"410400501:15:1","speaker":"Alice","text":"W-Well, I didn't quite mean it\nlike that...","pose":105401011,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我、我不是那个意思……"}]},{"id":16,"order":16,"actions":[{"uid":"410400501:16:1","speaker":"Alice","text":"I was simply saying that I cannot\nabide this place.","pose":105401011,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我只是说我无法忍受这个地方。"},{"uid":"410400501:16:2","speaker":"Asuna","text":"","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":17,"order":17,"actions":[{"uid":"410400501:17:1","speaker":"???","text":"Heeeey! Kiritoooo!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"嘿嘿！桐人啊！"},{"uid":"410400501:17:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400501:17:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410400501:18:1","speaker":"Kirito","text":"That must be our welcome party!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那一定是我们的欢迎会了！"},{"uid":"410400501:18:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":19,"order":19,"actions":[{"uid":"410400501:19:1","speaker":"Liz","text":"Welcome to Leprechaun territory!","pose":10070404,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"欢迎来到小矮妖领地！"},{"uid":"410400501:19:2","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":20,"order":20,"actions":[{"uid":"410400501:20:1","speaker":"Rain","text":"Thank you for making the journey\nin such foul weather. Oh, who am I\nkidding? It's always like this!","pose":10120104,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"谢谢你们在这么糟糕的天气里赶来。哦，我在和谁开玩笑呢？总是这样！"},{"uid":"410400501:20:2","speaker":"Liz","text":"","pose":10070404,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":21,"order":21,"actions":[{"uid":"410400501:21:1","speaker":"Asuna","text":"Thank you for coming to greet us\nin this mess!","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谢谢你在这乱七八糟的地方来迎接我们！"},{"uid":"410400501:21:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410400501:22:1","speaker":"Liz","text":"Oh, please! It's the least we\ncould do after you came all\nthis way.","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"哦，求你了！这是你千里迢迢而来之后我们能做的最起码的事情。"},{"uid":"410400501:22:2","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":23,"order":23,"actions":[{"uid":"410400501:23:1","speaker":"Liz","text":"Now, let's ditch the formalities\nso I can show you around our\nhome turf as a friend!","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"现在，让我们抛开繁文缛节，我可以以朋友的身份带你参观我们的主场！"},{"uid":"410400501:23:2","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":24,"order":24,"actions":[{"uid":"410400501:24:1","speaker":"Kirito","text":"That'd be great.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那就太好了。"},{"uid":"410400501:24:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":25,"order":25,"actions":[{"uid":"410400501:25:1","speaker":"Alice","text":"Liz and Rain... So you're Kirito's\nLeprechaun compatriots...","pose":10540105,"background":"bg_event_swamp","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"莉兹和蕾茵...所以你们是桐人的小矮妖同胞..."},{"uid":"410400501:25:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400501:25:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":26,"order":26,"actions":[{"uid":"410400501:26:1","speaker":"Eugeo","text":"They'll be assisting us in our\nsearch for the Divine Object\nin this region.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们将协助我们在该地区寻找神器。"},{"uid":"410400501:26:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400501:26:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":27,"order":27,"actions":[{"uid":"410400501:27:1","speaker":"Asuna","text":"Yep!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的！"},{"uid":"410400501:27:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400501:27:3","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":28,"order":28,"actions":[{"uid":"410400501:28:1","speaker":"Liz","text":"And guess what!\nWe already know where it is.","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"你猜怎么着！我们已经知道它在哪里了。"},{"uid":"410400501:28:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:28:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":29,"order":29,"actions":[{"uid":"410400501:29:1","speaker":"Alice","text":"You do?!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"是吗？！"},{"uid":"410400501:29:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400501:29:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":30,"order":30,"actions":[{"uid":"410400501:30:1","speaker":"Kirito","text":"Wow, really?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哇，真的吗？"},{"uid":"410400501:30:2","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:30:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":31,"order":31,"actions":[{"uid":"410400501:31:1","speaker":"Eugeo","text":"Incredible! We'll be finished here\nin no time flat!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"难以置信！我们很快就会完成这里！"},{"uid":"410400501:31:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400501:31:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":32,"order":32,"actions":[{"uid":"410400501:32:1","speaker":"Kirito","text":"So where is it?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那它在哪里呢？"},{"uid":"410400501:32:2","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:32:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":33,"order":33,"actions":[{"uid":"410400501:33:1","speaker":"Rain","text":"It's in a vault on the Leprechaun\nlord's premises.","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"小矮妖领主宅邸的金库里。"},{"uid":"410400501:33:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400501:33:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":34,"order":34,"actions":[{"uid":"410400501:34:1","speaker":"Kirito","text":"What!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么！"},{"uid":"410400501:34:2","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:34:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":35,"order":35,"actions":[{"uid":"410400501:35:1","speaker":"Asuna","text":"Oh no...","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哦不……"}]},{"id":36,"order":36,"actions":[{"uid":"410400501:36:1","speaker":"Liz","text":"Oh no is right...","pose":10070402,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"噢，不对……"}]},{"id":37,"order":37,"actions":[{"uid":"410400501:37:1","speaker":"Liz","text":"In a way, this might be your\ntoughest challenge yet.","pose":10070402,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"在某种程度上，这可能是你迄今为止最艰巨的挑战。"},{"uid":"410400501:37:2","speaker":"Asuna","text":"","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:37:3","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":38,"order":38,"actions":[{"uid":"410400501:38:1","speaker":"Alice","text":"What does she mean by that?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"她这话是什么意思？"},{"uid":"410400501:38:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400501:38:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":39,"order":39,"actions":[{"uid":"410400501:39:1","speaker":"Kirito","text":"Basically that someone else beat\nus to the Divine Object in this\nterritory.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"基本上是别人先于我们进入了这片领地的神器。"},{"uid":"410400501:39:2","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:39:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410400501:40:1","speaker":"Kirito","text":"I'd ask how tightly it's being\nguarded, but I think I already\nknow the answer...","pose":100115072,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我想问它的守卫有多严密，但我想我已经知道答案了……"},{"uid":"410400501:40:2","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:40:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":41,"order":41,"actions":[{"uid":"410400501:41:1","speaker":"Rain","text":"Remember, we're widely known\nas a race of blacksmiths...","pose":10120102,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"记住，我们是众所周知的铁匠种族……"},{"uid":"410400501:41:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400501:41:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410400501:42:1","speaker":"Rain","text":"We know our stuff when it comes\nto items and materials.","pose":10120102,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"我们对物品和材料了如指掌。"},{"uid":"410400501:42:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400501:42:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":43,"order":43,"actions":[{"uid":"410400501:43:1","speaker":"Liz","text":"Especially when they're all anyone\ncan talk about, like these Divine\nObjects.","pose":10070402,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"尤其是当它们是任何人都可以谈论的时候，比如这些神物。"},{"uid":"410400501:43:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:43:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410400501:44:1","speaker":"Rain","text":"And all they ever say is how\nunique and incredible it must be.","pose":10120102,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"他们只说它一定是多么独特和不可思议。"},{"uid":"410400501:44:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400501:44:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":45,"order":45,"actions":[{"uid":"410400501:45:1","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:45:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:45:3","speaker":"Kirito","text":"Ugh, this is bad... Very bad...","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呃，这样不好……很不好……"}]},{"id":46,"order":46,"actions":[{"uid":"410400501:46:1","speaker":"Asuna","text":"I know...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我知道……"}]},{"id":47,"order":47,"actions":[{"uid":"410400501:47:1","speaker":"Alice","text":"What's so bad about safeguarding\nthat which is yours? Surely we can\nnegotiate.","pose":10540102,"background":"bg_event_swamp","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"守护自己的东西有什么不好？我们当然可以谈判。"},{"uid":"410400501:47:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400501:47:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":48,"order":48,"actions":[{"uid":"410400501:48:1","speaker":"Liz","text":"Well, you see, Alice, we\nLeprechauns are really, really\nglad we have this thing.","pose":10070402,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"好吧，你看，爱丽丝，我们妖精真的非常非常高兴我们有这个东西。"},{"uid":"410400501:48:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:48:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":49,"order":49,"actions":[{"uid":"410400501:49:1","speaker":"Liz","text":"So we won't just hand it over.","pose":10070402,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"所以我们不会直接把它交给你。"},{"uid":"410400501:49:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:49:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":50,"order":50,"actions":[{"uid":"410400501:50:1","speaker":"Eugeo","text":"Not even if we give you a bunch of\nmoney? You call it Yuld, right?","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"给你一大笔钱也不行吗？你管它叫 Yuld，对吗？"},{"uid":"410400501:50:2","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""},{"uid":"410400501:50:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":51,"order":51,"actions":[{"uid":"410400501:51:1","speaker":"Rain","text":"Yeah, I don't think you have that\nkind of money.","pose":10120102,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"是啊，我觉得你没有那么多钱。"}]},{"id":52,"order":52,"actions":[{"uid":"410400501:52:1","speaker":"Alice","text":"Suppose we find an item equal in\nvalue and arrange a trade?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"假设我们找到一个等值的物品并安排交易？"},{"uid":"410400501:52:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400501:52:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":53,"order":53,"actions":[{"uid":"410400501:53:1","speaker":"Liz","text":"It's easy for you to say that,\nbut I can't think of another\nitem as rare as this one.","pose":100704062,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"你说起来很容易，但我想不出还有比这更稀有的东西了。"},{"uid":"410400501:53:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:53:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":54,"order":54,"actions":[{"uid":"410400501:54:1","speaker":"Alice","text":"Well then. Should negotiations\nfail, I suppose you'll not object\nto us taking it by force?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那好吧。如果谈判失败的话，我想你不会反对我们武力夺取吧？"},{"uid":"410400501:54:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400501:54:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":55,"order":55,"actions":[{"uid":"410400501:55:1","speaker":"Asuna","text":"Wait, what?!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"等等，什么？！"},{"uid":"410400501:55:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400501:55:3","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""}]},{"id":56,"order":56,"actions":[{"uid":"410400501:56:1","speaker":"Alice","text":"I'm sorry, is there a truce I am\nunaware of? Are the factions of\nthis world not at war?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"抱歉，是不是有什么我不知道的休战协议？这个世界的派系不是在打仗吗？"},{"uid":"410400501:56:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400501:56:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":57,"order":57,"actions":[{"uid":"410400501:57:1","speaker":"Alice","text":"Is battle not an option when\nnegotiations break down?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"谈判破裂就不能选择战斗吗？"},{"uid":"410400501:57:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400501:57:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":58,"order":58,"actions":[{"uid":"410400501:58:1","speaker":"Kirito","text":"Well, when you put it that way...\nIt's never totally off the table,\nbut...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，当你这么说的时候……它从来都不是完全不可能的，但是……"},{"uid":"410400501:58:2","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:58:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":59,"order":59,"actions":[{"uid":"410400501:59:1","speaker":"Liz","text":"Watch it, Kirito! We're\nLeprechauns too, in case\nyou've forgotten!","pose":100704082,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"小心点，桐人！我们也是小妖精，以防你忘记了！"},{"uid":"410400501:59:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:59:3","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":60,"order":60,"actions":[{"uid":"410400501:60:1","speaker":"Rain","text":"Believe me, I want to just hand it\nover to you guys, but you see the\nposition we're in...","pose":101201022,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"相信我，我想把它交给你们，但你们看到我们现在的处境了……"},{"uid":"410400501:60:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400501:60:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":61,"order":61,"actions":[{"uid":"410400501:61:1","speaker":"Kirito","text":"Well, there's no harm in\nnegotiating. Let's start there.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，谈判总没有坏处。让我们从这里开始吧。"},{"uid":"410400501:61:2","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:61:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":62,"order":62,"actions":[{"uid":"410400501:62:1","speaker":"Kirito","text":"If the negotiations fall apart,\nwe'll say that we are prepared\nto take it by force.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果谈判破裂，我们会说我们准备以武力夺取。"}]},{"id":63,"order":63,"actions":[{"uid":"410400501:63:1","speaker":"Liz","text":"Geez, you guys aren't messing\naround... I expected that from\nKirito, but not the rest of you...","pose":100704062,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"哎呀，你们这不是在胡闹吗……我以为桐人会这么说，但你们其他人却没想到……"}]},{"id":64,"order":64,"actions":[{"uid":"410400501:64:1","speaker":"Asuna","text":"I'm sorry, Liz.\nIt's nothing personal.","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"对不起，莉兹。这不是什么个人的事情。"}]},{"id":65,"order":65,"actions":[{"uid":"410400501:65:1","speaker":"Liz","text":"*sigh*... Yeah, I hear you.","pose":10070402,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"*叹息*...是的，我听到了。"}]},{"id":66,"order":66,"actions":[{"uid":"410400501:66:1","speaker":"Liz","text":"Okay, I'll talk to the higher-ups\nand see what I can do.","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"好吧，我去和高层谈谈，看看能做些什么。"}]},{"id":67,"order":67,"actions":[{"uid":"410400501:67:1","speaker":"Kirito","text":"Thanks!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"谢谢！"}]},{"id":68,"order":68,"actions":[{"uid":"410400501:68:1","speaker":"Liz","text":"I wouldn't get your hopes up,\nthough.","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"不过我不会让你抱太大希望。"},{"uid":"410400501:68:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":69,"order":69,"actions":[{"uid":"410400501:69:1","speaker":"Kirito","text":"I just got a message from Liz.","pose":10011505,"background":"bg_event_swamp","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我刚刚收到莉兹的消息。"},{"uid":"410400501:69:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410400501:70:1","speaker":"Asuna","text":"And? What does it say?","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"然后呢？它说什么？"}]},{"id":71,"order":71,"actions":[{"uid":"410400501:71:1","speaker":"Kirito","text":"Negotiations failed, just as we\nexpected they would.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"谈判失败了，正如我们所料。"}]},{"id":72,"order":72,"actions":[{"uid":"410400501:72:1","speaker":"Kirito","text":"Seems they also said any trade of\nrare items is also off the table.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好像也说了，稀有物品的交易也是不可能的。"},{"uid":"410400501:72:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":73,"order":73,"actions":[{"uid":"410400501:73:1","speaker":"Alice","text":"So? What do we do now?","pose":105401022,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"所以呢？我们现在做什么？"},{"uid":"410400501:73:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":74,"order":74,"actions":[{"uid":"410400501:74:1","speaker":"Kirito","text":"It seems she's already told them\nhow we intend to respond.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来她已经告诉他们我们打算如何应对了。"},{"uid":"410400501:74:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":75,"order":75,"actions":[{"uid":"410400501:75:1","speaker":"Asuna","text":"So we take it by force?","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那我们就用武力夺取吧？"}]},{"id":76,"order":76,"actions":[{"uid":"410400501:76:1","speaker":"Kirito","text":"We take it by force.\nGet ready to break\ninto their vault.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们用武力夺取。准备好闯入他们的金库。"},{"uid":"410400501:76:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":77,"order":77,"actions":[{"uid":"410400501:77:1","speaker":"Eugeo","text":"I must admit I don't relish\nthe idea of playing a thief.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我必须承认我不喜欢扮演小偷。"},{"uid":"410400501:77:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410400501:78:1","speaker":"Kirito","text":"Well, we've already told them\nwe're going to steal it, if that\nhelps.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，我们已经告诉他们我们要偷它了，如果有帮助的话。"},{"uid":"410400501:78:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":79,"order":79,"actions":[{"uid":"410400501:79:1","speaker":"Kirito","text":"Besides, they knew this was one\npossible outcome when they agreed\nto negotiate.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"而且，他们在同意谈判时就知道这是可能的结果。"}]},{"id":80,"order":80,"actions":[{"uid":"410400501:80:1","speaker":"Kirito","text":"It's not sneaky thievery so much\nas it is a declaration of war.\nWe know what we're getting into.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"与其说是偷偷摸摸的盗窃，不如说是宣战。我们知道我们将面临什么。"},{"uid":"410400501:80:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":81,"order":81,"actions":[{"uid":"410400501:81:1","speaker":"Eugeo","text":"I see. So stealing is prohibited\nhere as well...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我明白了。所以这里也禁止偷窃......"},{"uid":"410400501:81:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":82,"order":82,"actions":[{"uid":"410400501:82:1","speaker":"Alice","text":"As long as you are comfortable\nwith the decision, I have no\nobjections.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"只要你觉得舒服，我没有异议。"},{"uid":"410400501:82:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":83,"order":83,"actions":[{"uid":"410400501:83:1","speaker":"Asuna","text":"We don't have the numbers to\nattack them head on, though,\ndo we?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们没有正面攻击他们的人数，不是吗？"},{"uid":"410400501:83:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":84,"order":84,"actions":[{"uid":"410400501:84:1","speaker":"Kirito","text":"Of course not.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"当然不是。"}]},{"id":85,"order":85,"actions":[{"uid":"410400501:85:1","speaker":"Kirito","text":"We should split up and infiltrate\ntheir territory at night, which\nis my strong suit as a Spriggan.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"晚上分头潜入他们的领地，这是我作为影精灵的强项。"},{"uid":"410400501:85:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410400501:86:1","speaker":"Alice","text":"...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."},{"uid":"410400501:86:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":87,"order":87,"actions":[{"uid":"410400501:87:1","speaker":"Eugeo","text":"...","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"..."},{"uid":"410400501:87:2","speaker":"Alice","text":"","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":88,"order":88,"actions":[{"uid":"410400501:88:1","speaker":"Kirito","text":"Huh? Why'd you all go quiet?","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊？怎么大家都安静了？"},{"uid":"410400501:88:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":89,"order":89,"actions":[{"uid":"410400501:89:1","speaker":"Asuna","text":"Ha ha! Your love of battle is just\nso...un-Spriggan of you.","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哈哈！你对战斗的热爱是如此...un-影精灵。"}]},{"id":90,"order":90,"actions":[{"uid":"410400501:90:1","speaker":"Asuna","text":"I'm pretty sure even Alice and\nEugeo can feel that too.","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我相信爱丽丝和尤吉欧也能感觉到。"}]},{"id":91,"order":91,"actions":[{"uid":"410400501:91:1","speaker":"Kirito","text":"Oh...","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哦……"}]},{"id":92,"order":92,"actions":[{"uid":"410400501:92:1","speaker":"Kirito","text":"...","pose":10011505,"background":"bg_event_corridor","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410400501:92:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410400501:93:1","speaker":"Alice","text":"Are you two truly okay with\nthis plan?","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你们两个真的同意这个方案吗？"},{"uid":"410400501:93:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":94,"order":94,"actions":[{"uid":"410400501:94:1","speaker":"Alice","text":"Will this shadow magic allow you\nto sneak into the vault undetected\nby the enemy?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这个暗影魔法能让你在不被敌人发现的情况下潜入金库吗？"},{"uid":"410400501:94:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":95,"order":95,"actions":[{"uid":"410400501:95:1","speaker":"Kirito","text":"It should, yeah.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"应该是的。"},{"uid":"410400501:95:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":96,"order":96,"actions":[{"uid":"410400501:96:1","speaker":"Asuna","text":"They'll probably be expecting us\nto sneak in, though.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不过他们可能会期待我们潜入。"}]},{"id":97,"order":97,"actions":[{"uid":"410400501:97:1","speaker":"Kirito","text":"Yeah, I expect they'll have more\npatrols than usual. Maybe even\nsome with reveal magic.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，我预计他们的巡逻次数会比平时更多。也许甚至有一些具有揭露魔法。"},{"uid":"410400501:97:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":98,"order":98,"actions":[{"uid":"410400501:98:1","speaker":"Eugeo","text":"I'm beginning to suspect it would\nbe better not to have told them\nwe're coming...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我开始怀疑最好不要告诉他们我们要来......"},{"uid":"410400501:98:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410400501:99:1","speaker":"Eugeo","text":"But that's not really your style,\nis it?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"但这不是你的风格，是吗？"},{"uid":"410400501:99:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410400501:100:1","speaker":"Kirito","text":"Ha ha, you're starting to figure\nme out, Eugeo.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，你开始猜透我了，尤吉欧。"},{"uid":"410400501:100:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410400501:101:1","speaker":"Kirito","text":"Sure, part of me would love to\nplay by the rules all the time.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"当然，我的一部分喜欢一直遵守规则。"}]},{"id":102,"order":102,"actions":[{"uid":"410400501:102:1","speaker":"Kirito","text":"But I figured Liz and the other\nLeprechauns already know we\nwant the Divine Objects,","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是我想莉兹和其他妖精已经知道我们想要神器，"}]},{"id":103,"order":103,"actions":[{"uid":"410400501:103:1","speaker":"Kirito","text":"so if anyone planned to steal\ntheirs, they'd realize it was us\nanyway.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以如果有人打算偷他们的东西，他们无论如何都会意识到是我们。"},{"uid":"410400501:103:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":104,"order":104,"actions":[{"uid":"410400501:104:1","speaker":"Eugeo","text":"Indeed, I see what you mean.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"确实，我明白你的意思了。"},{"uid":"410400501:104:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410400501:105:1","speaker":"Alice","text":"Quiet! There's a patrol right—!","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"安静！有巡逻队对吧——！"}]},{"id":106,"order":106,"actions":[{"uid":"410400501:106:1","speaker":"Leprechaun","text":"Intruders! They've come to steal\nour Divine Object!","pose":2,"background":"bg_event_corridor","item":"","illustration":"","speaker_zh":"小矮妖","text_zh":"入侵者！他们来偷我们的神器了！"},{"uid":"410400501:106:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400501:106:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":107,"order":107,"actions":[{"uid":"410400501:107:1","speaker":"Leprechaun","text":"They can't have gone far!\nSearch the area!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"小矮妖","text_zh":"他们不可能走多远的！搜索该地区！"}]},{"id":108,"order":108,"actions":[{"uid":"410400501:108:1","speaker":"Kirito","text":"Argh, they found us sooner than\nI'd hoped they would...","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊，他们发现我们的时间比我希望的还要早……"},{"uid":"410400501:108:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410400501:109:1","speaker":"Asuna","text":"They've got a fair number of\npatrols out. They really want to\nhold onto this Divine Object...","pose":100209072,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他们有相当数量的巡逻人员。他们真的很想保住这个神器……"},{"uid":"410400501:109:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":110,"order":110,"actions":[{"uid":"410400501:110:1","speaker":"Alice","text":"Then there is no doubt that it\ncontains the goddess's awesome\npower.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那么毫无疑问，它蕴含着女神的可怕力量。"},{"uid":"410400501:110:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":111,"order":111,"actions":[{"uid":"410400501:111:1","speaker":"Alice","text":"Which is precisely why we cannot\nlet it fall into the hands of\nthe weak.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这就是为什么我们不能让它落入弱者手中。"}]},{"id":112,"order":112,"actions":[{"uid":"410400501:112:1","speaker":"Alice","text":"I'm sorry to say only a fool would\nbe unaware of that fact.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"很抱歉，只有傻子才会不知道这个事实。"},{"uid":"410400501:112:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":113,"order":113,"actions":[{"uid":"410400501:113:1","speaker":"Kirito","text":"Well, either way, the Leprechauns\nseem particularly obsessed with\nacquiring items and weapons.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，不管怎样，妖精们似乎特别热衷于获取物品和武器。"},{"uid":"410400501:113:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":114,"order":114,"actions":[{"uid":"410400501:114:1","speaker":"Kirito","text":"It's kind of their thing.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这是他们的事。"}]},{"id":115,"order":115,"actions":[{"uid":"410400501:115:1","speaker":"Kirito","text":"And once they've acquired a rare\nnew item, their pride kicks in and\nkeeps them from giving it up.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"一旦获得了稀有的新物品，他们的自豪感就会油然而生，让他们无法放弃。"},{"uid":"410400501:115:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410400501:116:1","speaker":"Eugeo","text":"...","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"..."},{"uid":"410400501:116:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":117,"order":117,"actions":[{"uid":"410400501:117:1","speaker":"Eugeo","text":"You know, I've been wondering...","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你知道，我一直在想……"},{"uid":"410400501:117:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410400501:118:1","speaker":"Kirito","text":"What about?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那又怎么样？"},{"uid":"410400501:118:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":119,"order":119,"actions":[{"uid":"410400501:119:1","speaker":"Leprechaun","text":"There they are! I've found the\nintruders!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"小矮妖","text_zh":"他们来了！我发现入侵者了！"}]},{"id":120,"order":120,"actions":[{"uid":"410400501:120:1","speaker":"Asuna","text":"They found us!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他们找到我们了！"}]},{"id":121,"order":121,"actions":[{"uid":"410400501:121:1","speaker":"Kirito","text":"Hold that thought, Eugeo!\nWe've gotta run!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"抱住这个念头，尤吉欧！我们得跑！"},{"uid":"410400501:121:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":122,"order":122,"actions":[{"uid":"410400501:122:1","speaker":"Eugeo","text":"G-Got it!","pose":105302022,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"明白、明白了！"},{"uid":"410400501:122:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":123,"order":123,"actions":[{"uid":"410400501:123:1","speaker":"Kirito","text":"Whew...","pose":100115022,"background":"bg_event_swamp","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呼……"},{"uid":"410400501:123:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400501:123:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":124,"order":124,"actions":[{"uid":"410400501:124:1","speaker":"Asuna","text":"I don't know how, but we got away.","pose":100209092,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我不知道怎么办，但我们还是逃走了。"}]},{"id":125,"order":125,"actions":[{"uid":"410400501:125:1","speaker":"Eugeo","text":"That we did... Wait a minute.","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们做到了……等一下。"}]},{"id":126,"order":126,"actions":[{"uid":"410400501:126:1","speaker":"Kirito","text":"What is it? Hey, where's Alice?","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？嘿，爱丽丝在哪里？"}]},{"id":127,"order":127,"actions":[{"uid":"410400501:127:1","speaker":"Asuna","text":"Did we lose Alice?!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们是不是输了爱丽丝？！"}]},{"id":128,"order":128,"actions":[{"uid":"410400501:128:1","speaker":"Eugeo","text":"We must have split up in the\nscramble to escape. We have\nto find her!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们一定是在争先恐后的逃跑过程中分开了。我们必须找到她！"}]},{"id":129,"order":129,"actions":[{"uid":"410400501:129:1","speaker":"Kirito","text":"Eugeo, wait! I know how you feel,\nbut don't jump into the fire when\nwe've just escaped the frying pan!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧，等等！我知道你的感受，但是当我们刚刚逃离煎锅时，不要跳进火里！"}]},{"id":130,"order":130,"actions":[{"uid":"410400501:130:1","speaker":"Asuna","text":"Kirito's right. We'll get caught\nfor sure if we go looking for her.\nI'm sorry.","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人说得对。如果我们去找她肯定会被抓住的。对不起。"}]},{"id":131,"order":131,"actions":[{"uid":"410400501:131:1","speaker":"Asuna","text":"I'm worried about her too,\nbut we need a plan.","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我也担心她，但我们需要一个计划。"}]},{"id":132,"order":132,"actions":[{"uid":"410400501:132:1","speaker":"Kirito","text":"Exactly.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没错。"}]},{"id":133,"order":133,"actions":[{"uid":"410400501:133:1","speaker":"Eugeo","text":"I understand.","pose":105302062,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我明白了。"}]},{"id":134,"order":134,"actions":[{"uid":"410400501:134:1","speaker":"Kirito","text":"...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."}]},{"id":135,"order":135,"actions":[{"uid":"410400501:135:1","speaker":"Kirito","text":"Eugeo, you were about to say\nsomething earlier. Was it related\nto securing the Divine Object?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧，你刚才还想说什么呢。是否与保护神器有关？"}]},{"id":136,"order":136,"actions":[{"uid":"410400501:136:1","speaker":"Eugeo","text":"It was. So I understand that the\nLeprechauns don't want to give\nit away because it's valuable,","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的。所以我明白妖精们不想把它送出去，因为它很有价值，"}]},{"id":137,"order":137,"actions":[{"uid":"410400501:137:1","speaker":"Eugeo","text":"but suppose we could get them\nto see how dangerous it is.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"但是假设我们可以让他们看看这有多危险。"}]},{"id":138,"order":138,"actions":[{"uid":"410400501:138:1","speaker":"Eugeo","text":"They'd have no choice but to hand\nit over. Right?","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们没办法，只能交出。正确的？"}]},{"id":139,"order":139,"actions":[{"uid":"410400501:139:1","speaker":"Kirito","text":"It's possible...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"有可能……"}]},{"id":140,"order":140,"actions":[{"uid":"410400501:140:1","speaker":"Eugeo","text":"We've acquired two Divine Objects\nthus far, and in both fights we've\ncome to understand their power.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"目前为止我们已经获得了两把神器，在两次战斗中我们都了解了它们的威力。"}]},{"id":141,"order":141,"actions":[{"uid":"410400501:141:1","speaker":"Eugeo","text":"We've seen the awful power of the\nForces of Darkness,","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们见识过黑暗势力的可怕力量，"}]},{"id":142,"order":142,"actions":[{"uid":"410400501:142:1","speaker":"Eugeo","text":"or what you call monsters,\nmobilize when our battles\ninvolve the Divine Objects.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"或者你们所说的怪物，当我们的战斗涉及到神器时就出动吧。"}]},{"id":143,"order":143,"actions":[{"uid":"410400501:143:1","speaker":"Kirito","text":"What!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么！"}]},{"id":144,"order":144,"actions":[{"uid":"410400501:144:1","speaker":"Asuna","text":"Yeah, the enemies from Jotunheimr\nare tough. And let's not forget\nthe whale creature we fought!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，幽兹海姆的敌人很强悍。我们不要忘记我们所战斗的鲸鱼生物！"}]},{"id":145,"order":145,"actions":[{"uid":"410400501:145:1","speaker":"Kirito","text":"Eugeo, are you suggesting the\npower of the Divine Objects\nattracts monsters?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧，你是说神器的力量会吸引怪物吗？"}]},{"id":146,"order":146,"actions":[{"uid":"410400501:146:1","speaker":"Eugeo","text":"That's my theory, yes.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的，这是我的理论。"}]},{"id":147,"order":147,"actions":[{"uid":"410400501:147:1","speaker":"Eugeo","text":"If only we could prove it, I can't\nimagine they'd insist on holding\nonto the Divine Object.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"如果我们能证明这一点，我无法想象他们会坚持持有神器。"}]},{"id":148,"order":148,"actions":[{"uid":"410400501:148:1","speaker":"Kirito","text":"Hm, you may have a point there...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，你说的可能有道理……"}]},{"id":149,"order":149,"actions":[{"uid":"410400501:149:1","speaker":"Alice","text":"Ungh...","pose":105401012,"background":"bg_event_corridor","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"呃……"},{"uid":"410400501:149:2","speaker":"Liz","text":"","pose":10070405,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":""},{"uid":"410400501:149:3","speaker":"Rain","text":"","pose":10120105,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":""}]},{"id":150,"order":150,"actions":[{"uid":"410400501:150:1","speaker":"Liz","text":"Well well, looks like we caught\nourselves an Alice!","pose":10070401,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"好吧好吧，看来我们抓到了爱丽丝！"}]},{"id":151,"order":151,"actions":[{"uid":"410400501:151:1","speaker":"Liz","text":"You're strong, Alice, I'll give you\nthat. But you don't get Alfheim's\nmagic. That's your Achilles heel.","pose":10070404,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"你很强啊，爱丽丝，我给你。但你并没有体会到阿尔普海姆的魔力。这就是你的阿喀琉斯之踵。"}]},{"id":152,"order":152,"actions":[{"uid":"410400501:152:1","speaker":"Alice","text":"So, that strange force that\ncaptured me was fairy magic!","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"原来，那股俘获我的奇异力量就是妖精魔法！"}]},{"id":153,"order":153,"actions":[{"uid":"410400501:153:1","speaker":"Liz","text":"Bingo!","pose":10070404,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"宾果！"}]},{"id":154,"order":154,"actions":[{"uid":"410400501:154:1","speaker":"Rain","text":"Just consider yourself lucky that\nLiz and I were the ones to find\nyou!","pose":10120104,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"你就觉得自己很幸运，我和莉兹找到了你！"}]},{"id":155,"order":155,"actions":[{"uid":"410400501:155:1","speaker":"Alice","text":"What good fortune is there in\nbeing captured?! Release these\nchains right this instant!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"被抓走有什么福气？！立即释放这些锁链！"}]},{"id":156,"order":156,"actions":[{"uid":"410400501:156:1","speaker":"Liz","text":"You know we can't do that, Alice.\nWe may be Kirito's friends, but\nwe're still Leprechauns.","pose":10070406,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"你知道我们不能这么做，爱丽丝。我们可能是桐人的朋友，但我们仍然是妖精。"}]},{"id":157,"order":157,"actions":[{"uid":"410400501:157:1","speaker":"Liz","text":"So aside from the fact that every\nrace in the game is after these\nDivine Objects,","pose":10070406,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"所以除了游戏中的每场比赛都是在这些神器之后，"}]},{"id":158,"order":158,"actions":[{"uid":"410400501:158:1","speaker":"Liz","text":"we're all at war with each other.\nWe can't start playing favorites.","pose":10070406,"background":"","item":"","illustration":"","speaker_zh":"莉兹","text_zh":"我们都在互相争斗。我们无法开始播放最爱。"}]},{"id":159,"order":159,"actions":[{"uid":"410400501:159:1","speaker":"Alice","text":"These chains are keeping my powers\nat bay, aren't they?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这些锁链限制了我的力量，不是吗？"}]},{"id":160,"order":160,"actions":[{"uid":"410400501:160:1","speaker":"Alice","text":"I can't use Enhance Armament\nor any of the Sacred Arts...","pose":105401062,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我不能使用武装完全支配术或任何神圣术……"}]},{"id":161,"order":161,"actions":[{"uid":"410400501:161:1","speaker":"Rain","text":"Hehe, pretty handy, huh?\nIt's a true Leprechaun original!","pose":10120104,"background":"","item":"","illustration":"","speaker_zh":"蕾茵","text_zh":"呵呵，很方便吧？这是真正的小矮妖原创！"}]},{"id":162,"order":162,"actions":[{"uid":"410400501:162:1","speaker":"Alice","text":"It works as intended, yes.\nYou Leprechauns are quite\npowerful.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"按预期工作，是的。你们妖精真是太强大了。"}]}]};
